16	// maxCatalogPage bounds one _catalog page: 1000 names of at most 255 bytes fit
17	// well under it.
18	const maxCatalogPage = 1 << 20
19	
20	// ListCatalogContext walks the registry's /v2/_catalog from apiURL; it is
21	// ListCatalogUnderContext with an empty prefix.
22	func ListCatalogContext(ctx context.Context, apiURL, username, password string, maxPages, pageSize int) (names []string, truncated bool, err error) {
23		return ListCatalogUnderContext(ctx, apiURL, "", username, password, maxPages, pageSize)
24	}
25	
26	// ListCatalogUnderContext walks the catalog of the repository at prefix,
27	// /v2/<prefix>/_catalog (a Nexus group member, DEVDESK-579), or the registry's
28	// /v2/_catalog when prefix is empty. Names come back as the server sent them,
29	// without the prefix: rebuilding "<prefix>/<name>" is the caller's job.
30	// It asks pageSize names per page and follows Link rel="next" for at most
31	// maxPages pages. truncated is true when the walk stopped with names left: page
32	// cap reached with a next link, more than maxPages*pageSize names, or a next
33	// link to another origin (never followed: the Basic credentials and the token
34	// are not sent to it). HTTP 3xx redirects follow registryHTTPClient, which
35	// refuses off-origin ones (RefuseOffOriginRedirect, DEVDESK-410).
36	// Authentication is the tag flow's (Basic, then Bearer on a challenge, token
37	// kept across pages); a non-200 answer is a *StatusError. A prefix that
38	// checkCatalogPrefix refuses is an error before any request.
39	func ListCatalogUnderContext(ctx context.Context, apiURL, prefix, username, password string, maxPages, pageSize int) (names []string, truncated bool, err error) {
40		if maxPages <= 0 || pageSize <= 0 {
41			return nil, false, fmt.Errorf("catalog walk needs positive limits, got %d pages of %d", maxPages, pageSize)
42		}
43		path, err := catalogPath(prefix)
44		if err != nil {
45			return nil, false, err
46		}
47		next := strings.TrimSuffix(apiURL, "/") + path + "?n=" + strconv.Itoa(pageSize)
48		token := ""
49		for page := 0; next != ""; page++ {
50			if page == maxPages {
51				return names, true, nil
52			}
53			body, link, usedToken, err := registryGETBoundedContext(ctx, next, username, password, token, maxCatalogPage)
54			if err != nil {
55				return nil, false, err
56			}
57			token = usedToken
58			var result struct {
59				Repositories []string `json:"repositories"`
60			}
61			if err := json.Unmarshal(body, &result); err != nil {
62				return nil, false, fmt.Errorf("decode catalog response: %w", err)
63			}
64			names = append(names, result.Repositories...)
65			if len(names) > maxPages*pageSize {
66				return names[:maxPages*pageSize], true, nil
67			}
68			current := next
69			if next = resolveNext(current, link); next != "" && !sameOrigin(current, next) {
70				return names, true, nil
71			}
72		}
73		return names, false, nil
74	}
