76	// catalogPath is the escaped catalog path for prefix: "/v2/_catalog" for an
77	// empty prefix, "/v2/<seg>/<seg>/_catalog" otherwise, each segment escaped
78	// with url.PathEscape so it stays one path segment on the wire.
79	func catalogPath(prefix string) (string, error) {
80		if prefix == "" {
81			return "/v2/_catalog", nil
82		}
83		if err := checkCatalogPrefix(prefix); err != nil {
84			return "", err
85		}
86		segments := strings.Split(prefix, "/")
87		for i, seg := range segments {
88			segments[i] = url.PathEscape(seg)
89		}
90		return "/v2/" + strings.Join(segments, "/") + "/_catalog", nil
