93	// checkCatalogPrefix refuses, before any request, a prefix that could leave
94	// the member's catalog path or that no repository name holds: an empty segment
95	// (so a leading, trailing or doubled slash), "." or "..", any ".." (read
96	// literally, so "a..b" too), a backslash, a segment of spaces only, and any
97	// control character (NUL included). The error names the rule, never the
98	// prefix's surroundings or any credential.
99	func checkCatalogPrefix(prefix string) error {
100		if strings.Contains(prefix, "..") {
101			return errors.New("catalog prefix refused: contains \"..\"")
102		}
103		if strings.ContainsRune(prefix, '\\') {
104			return errors.New("catalog prefix refused: contains a backslash")
105		}
106		if strings.IndexFunc(prefix, unicode.IsControl) >= 0 {
107			return errors.New("catalog prefix refused: contains a control character")
108		}
109		for _, seg := range strings.Split(prefix, "/") {
110			switch {
