122	// registryGETBoundedContext is registryGETContext with an explicit body cap:
123	// a body over limit is an error, not a silent cut.
124	func registryGETBoundedContext(ctx context.Context, rawURL, username, password, token string, limit int64) (body []byte, link, usedToken string, err error) {
125		resp, token, err := registryDoContext(ctx, http.MethodGet, rawURL, "", username, password, token)
126		if err != nil {
127			return nil, "", token, err
128		}
129		defer func() { _ = resp.Body.Close() }()
130		if resp.StatusCode != http.StatusOK {
131			return nil, "", token, &StatusError{Code: resp.StatusCode, Source: SourceRegistry}
132		}
133		body, err = io.ReadAll(io.LimitReader(resp.Body, limit+1))
134		if err == nil && int64(len(body)) > limit {
135			err = errors.New("catalog page over " + strconv.FormatInt(limit, 10) + " bytes")
