143	// sameOrigin reports whether two absolute URLs share scheme, host and port.
144	func sameOrigin(a, b string) bool {
145		ua, errA := url.Parse(a)
146		ub, errB := url.Parse(b)
147		return errA == nil && errB == nil && ua.Scheme == ub.Scheme && ua.Host == ub.Host
148	}
