341	func TestListCatalogUnderContextNextOrigin(t *testing.T) {
342		var otherHits atomic.Int32
343		var otherAuth atomic.Value
344		other := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
345			otherHits.Add(1)
346			otherAuth.Store(r.Header.Get("Authorization"))
347			_, _ = fmt.Fprint(w, catalogBody("evil"))
348		}))
349		defer other.Close()
350	
351		t.Run("other origin is not followed and gets no credentials", func(t *testing.T) {
352			var log requestLog
353			srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
354				log.add(r)
355				w.Header().Set("Link", `<`+other.URL+`/v2/docker-hosted/_catalog?last=x>; rel="next"`)
356				_, _ = fmt.Fprint(w, catalogBody("first"))
357			}))
358			defer srv.Close()
359	
360			names, truncated, err := ListCatalogUnderContext(context.Background(), srv.URL, "docker-hosted", "user", "pass", 10, 1000)
